void format_socket_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *proto = (c->transport == PROTOCOL_TCP) ? "TCP" : "UDP";
    char ip[INET6_ADDRSTRLEN];
    ip[0] = '\0';
    int port = 0;

    switch (af) {
        case AF_INET: {
            struct sockaddr_in *sa = (struct sockaddr_in *)sock_addr;
            if (inet_ntop(AF_INET, &sa->sin_addr, ip, INET6_ADDRSTRLEN) == NULL) {
                *ip = '\0';
            }
            port = ntohs(sa->sin_port);
            break;
        }
        case AF_INET6: {
            struct sockaddr_in6 *sa = (struct sockaddr_in6 *)sock_addr;
            if (inet_ntop(AF_INET6, &sa->sin6_addr, ip, INET6_ADDRSTRLEN) == NULL) {
                *ip = '\0';
            }
            port = ntohs(sa->sin6_port);
            break;
        }
        case AF_UNIX: {
            struct sockaddr_un *sa = (struct sockaddr_un *)sock_addr;
            if (sa->sun_path[0] != '\0') {
                strncpy(ip, sa->sun_path, INET6_ADDRSTRLEN - 1);
                ip[INET6_ADDRSTRLEN - 1] = '\0';
            }
            break;
        }
        default:
            break;
    }

    if (ip[0] == '\0') {
        snprintf(addr, MAX_SOCKET_ADDRESS_LENGTH, "%s@%d", proto, af);
    } else if (af == AF_UNIX) {
        snprintf(addr, MAX_SOCKET_ADDRESS_LENGTH, "%s@%s", proto, ip);
    } else {
        snprintf(addr, MAX_SOCKET_ADDRESS_LENGTH, "%s@[%s]:%d", proto, ip, port);
    }
}

void format_socket_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *proto = (c->transport == tcp_transport) ? "tcp" : "udp";
    const char *ip_str = "";
    in_port_t port = 0;

    if (af == AF_INET) {
        struct sockaddr_in *s = (struct sockaddr_in *)sock_addr;
        ip_str = inet_ntop(AF_INET, &s->sin_addr, ip_str, INET_ADDRSTRLEN);
        port = ntohs(s->sin_port);
    } else if (af == AF_INET6) {
        struct sockaddr_in6 *s = (struct sockaddr_in6 *)sock_addr;
        ip_str = inet_ntop(AF_INET6, &s->sin6_addr, ip_str, INET6_ADDRSTRLEN);
        port = ntohs(s->sin6_port);
    } else if (af == AF_UNIX) {
        struct sockaddr_un *s = (struct sockaddr_un *)sock_addr;
        if (s->sun_path[0] != '\0') {
            ip_str = s->sun_path;
        } else {
            ip_str = "unix";
        }
    }

    if (ip_str[0] == '\0') {
        snprintf(addr, MAX_SOCKET_ADDR_STRLEN, "%s@%d", proto, af);
    } else if (af == AF_UNIX && strcmp(ip_str, "unix") == 0) {
        snprintf(addr, MAX_SOCKET_ADDR_STRLEN, "%s@%d", proto, af);
    } else {
        if (af == AF_UNIX) {
            snprintf(addr, MAX_SOCKET_ADDR_STRLEN, "%s@%s", proto, ip_str);
        } else {
            snprintf(addr, MAX_SOCKET_ADDR_STRLEN, "%s://%s:%hu", proto, ip_str, port);
        }
    }
}

void conn_sa2str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *proto = (c->transport == tcp_transport) ? "tcp" : "udp";
    const char *port = "";
    char buffer[NI_MAXHOST] = "";

    if (af == AF_INET || af == AF_INET6) {
        void *ip_addr;
        int port_num = 0;

        if (af == AF_INET) {
            struct sockaddr_in *s = (struct sockaddr_in *)sock_addr;
            ip_addr = &(s->sin_addr);
            port_num = ntohs(s->sin_port);
        } else {
            struct sockaddr_in6 *s = (struct sockaddr_in6 *)sock_addr;
            ip_addr = &(s->sin6_addr);
            port_num = ntohs(s->sin6_port);
        }

        if (inet_ntop(af, ip_addr, buffer, sizeof(buffer)) != NULL) {
            if (port_num != 0) {
                snprintf((char *)addr, NI_MAXHOST, "%s://%s:%d", proto, buffer, port_num);
            } else {
                snprintf((char *)addr, NI_MAXHOST, "%s://%s", proto, buffer);
            }
        } else {
            snprintf((char *)addr, NI_MAXHOST, "%s://[unknown]", proto);
        }
    } else if (af == AF_UNIX) {
        struct sockaddr_un *s = (struct sockaddr_un *)sock_addr;
        if (s->sun_path[0] != '\0') {
            snprintf((char *)addr, NI_MAXHOST, "unix:%s", s->sun_path);
        } else {
            snprintf((char *)addr, NI_MAXHOST, "unix://[abstract]");
        }
    } else {
        snprintf((char *)addr, NI_MAXHOST, "%s://[family %d]", proto, af);
    }
}

void conn_sockaddr_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    if (!addr || !sock_addr) {
        return;
    }

    *addr = '\0';

    if (af == AF_INET || af == AF_INET6) {
        char ip_str[INET6_ADDRSTRLEN];
        uint16_t port = 0;
        const void *addr_ptr = NULL;

        if (af == AF_INET) {
            struct sockaddr_in *s = (struct sockaddr_in *)sock_addr;
            addr_ptr = &(s->sin_addr);
            port = ntohs(s->sin_port);
        } else {
            struct sockaddr_in6 *s = (struct sockaddr_in6 *)sock_addr;
            addr_ptr = &(s->sin6_addr);
            port = ntohs(s->sin6_port);
        }

        if (inet_ntop(af, addr_ptr, ip_str, sizeof(ip_str))) {
            if (c->transport == ascii_transport) {
                snprintf(addr, MAXADDRSTRLEN, "%s", ip_str);
            } else {
                snprintf(addr, MAXADDRSTRLEN, "%s:%d", ip_str, port);
            }
        }
    } else if (af == AF_UNIX) {
        struct sockaddr_un *sun = (struct sockaddr_un *)sock_addr;
        if (sun->sun_path[0] != '\0') {
            snprintf(addr, MAXADDRSTRLEN, "%s", sun->sun_path);
        } else {
            snprintf(addr, MAXADDRSTRLEN, "UNIX (abstract)");
        }
    } else {
        snprintf(addr, MAXADDRSTRLEN, "AF_%d", af);
    }
}

void conn_sockaddr_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *proto = (c->transport == ascii_sock) ? "ascii" : "binary";
    const char *ip_str = "";

    switch (af) {
        case AF_INET: {
            struct sockaddr_in *s = (struct sockaddr_in *)sock_addr;
            ip_str = inet_ntop(AF_INET, &s->sin_addr, addr, NI_MAXHOST);
            if (ip_str) {
                snprintf(addr, NI_MAXHOST, "%s:%d", ip_str, ntohs(s->sin_port));
            }
            break;
        }
        case AF_INET6: {
            struct sockaddr_in6 *s = (struct sockaddr_in6 *)sock_addr;
            ip_str = inet_ntop(AF_INET6, &s->sin6_addr, addr, NI_MAXHOST);
            if (ip_str) {
                snprintf(addr, NI_MAXHOST, "%s:%d", ip_str, ntohs(s->sin6_port));
            }
            break;
        }
        case AF_UNIX: {
            struct sockaddr_un *s = (struct sockaddr_un *)sock_addr;
            snprintf(addr, NI_MAXHOST, "UNIX:%s", s->sun_path);
            break;
        }
        default:
            snprintf(addr, NI_MAXHOST, "<UNKNOWN>");
            break;
    }

    if (strlen(addr) == 0) {
        snprintf(addr, NI_MAXHOST, "%s", (af == AF_UNIX) ? "UNIX:<empty>" : proto);
    }
}
